def validate_scrape_options(options: Optional[ScrapeOptions]) -> Optional[ScrapeOptions]:
    """
    Validate and normalize scrape options.

    Args:
        options: Scraping options to validate

    Returns:
        Validated options or None

    Raises:
        ValueError: If options are invalid
    """
    if options is None:
        return None

    # Validate timeout
    if options.timeout is not None and options.timeout <= 0:
        raise ValueError("Timeout must be positive")

    # Validate wait_for
    if options.wait_for is not None and options.wait_for < 0:
        raise ValueError("wait_for must be non-negative")

    return options


def prepare_scrape_options(options: Optional[ScrapeOptions]) -> Optional[Dict[str, Any]]:
    """
    Prepare ScrapeOptions for API submission with manual snake_case to camelCase conversion.

    Args:
        options: ScrapeOptions to prepare

    Returns:
        Dictionary ready for API submission or None if options is None
    """
    if options is None:
        return None

    # Validate options first
    validated_options = validate_scrape_options(options)
    if validated_options is None:
        return None

    # Apply default values for None fields
    default_values = {
        "only_main_content": True,
        "mobile": False,
        "skip_tls_verification": True,
        "remove_base64_images": True,
        "fast_mode": False,
        "block_ads": True,
        "max_age": 14400000,
        "store_in_cache": True
    }

    # Convert to dict and handle manual snake_case to camelCase conversion
    options_data = validated_options.model_dump(exclude_none=True)

    # Apply defaults for None fields
    for field, default_value in default_values.items():
        if field not in options_data:
            options_data[field] = default_value

    scrape_data = {}

    # Manual field mapping for snake_case to camelCase conversion
    field_mappings = {
        "include_tags": "includeTags",
        "exclude_tags": "excludeTags",
        "only_main_content": "onlyMainContent",
        "wait_for": "waitFor",
        "skip_tls_verification": "skipTlsVerification",
        "remove_base64_images": "removeBase64Images",
        "fast_mode": "fastMode",
        "use_mock": "useMock",
        "block_ads": "blockAds",
        "store_in_cache": "storeInCache",
        "max_age": "maxAge",
        "min_age": "minAge",
        "redact_pii": "redactPII",
        "threat_protection": "threatProtection",
        "audit_metadata": "auditMetadata",
    }

    # Apply field mappings
    for snake_case, camel_case in field_mappings.items():
        if snake_case in options_data:
            scrape_data[camel_case] = options_data.pop(snake_case)

    # redactPII may be a nested object whose inner `replace_style` field
    # also needs camel-casing.
    if isinstance(scrape_data.get("redactPII"), dict):
        if "replace_style" in scrape_data["redactPII"]:
            scrape_data["redactPII"]["replaceStyle"] = scrape_data["redactPII"].pop(
                "replace_style"
            )

    # threatProtection is a nested object whose inner fields also need
    # camel-casing.
    if isinstance(scrape_data.get("threatProtection"), dict):
        threat_data = scrape_data["threatProtection"]
        for snake_case, camel_case in (
            ("risk_score_threshold", "riskScoreThreshold"),
            ("blocked_tlds", "blockedTlds"),
            ("failure_policy", "failurePolicy"),
        ):
            if snake_case in threat_data:
                threat_data[camel_case] = threat_data.pop(snake_case)

    # Handle special cases
    for key, value in options_data.items():
        if value is not None:
            if key == "integration":
                scrape_data["integration"] = (str(value).strip() or None)
                continue
            if key == "formats":
                # Handle formats conversion
                converted_formats: List[Any] = []

                # Prefer using original object to detect ScrapeFormats vs list
                original_formats = getattr(options, 'formats', None)

                if isinstance(original_formats, ScrapeFormats):
                    # Include explicit list first
                    if original_formats.formats:
                        for fmt in original_formats.formats:
                            if isinstance(fmt, str):
                                if fmt == "json":
                                    raise ValueError("json format must be an object with 'type', 'prompt', and 'schema' fields")
                                if fmt == "query":
                                    raise ValueError("query format must be an object with 'type' and 'prompt' fields")
                                if fmt == "question":
                                    raise ValueError("question format must be an object with 'type' and 'question' fields")
                                if fmt == "highlights":
                                    raise ValueError("highlights format must be an object with 'type' and 'query' fields")
                                converted_formats.append(_convert_format_string(fmt))
                            elif isinstance(fmt, dict):
                                fmt_type = _convert_format_string(fmt.get('type')) if fmt.get('type') else None
                                if fmt_type == 'json':
                                    validated_json = _validate_json_format({**fmt, 'type': 'json'})
                                    converted_formats.append(validated_json)
                                elif fmt_type == 'question':
                                    converted_formats.append(_validate_question_format(fmt))
                                elif fmt_type == 'highlights':
                                    converted_formats.append(_validate_highlights_format(fmt))
                                elif fmt_type == 'query':
                                    converted_formats.append(_validate_query_format(fmt))
                                elif fmt_type == 'screenshot':
                                    # Normalize screenshot options
                                    normalized = {**fmt, 'type': 'screenshot'}
                                    if 'full_page' in normalized:
                                        normalized['fullPage'] = normalized.pop('full_page')
                                    # Normalize viewport if it's a model instance
                                    vp = normalized.get('viewport')
                                    if hasattr(vp, 'model_dump'):
                                        normalized['viewport'] = vp.model_dump(exclude_none=True)
                                    converted_formats.append(normalized)
                                else:
                                    if 'type' in fmt:
                                        fmt['type'] = fmt_type or fmt['type']
                                    converted_formats.append(fmt)
                            elif hasattr(fmt, 'type'):
                                if fmt.type == 'json':
                                    converted_formats.append(_validate_json_format(fmt.model_dump()))
                                elif fmt.type == 'question':
                                    converted_formats.append(_validate_question_format(fmt.model_dump(exclude_none=True)))
                                elif fmt.type == 'highlights':
                                    converted_formats.append(_validate_highlights_format(fmt.model_dump(exclude_none=True)))
                                elif fmt.type == 'query':
                                    converted_formats.append(_validate_query_format(fmt.model_dump(exclude_none=True)))
                                elif fmt.type in ('changeTracking', 'change_tracking'):
                                    data = fmt.model_dump(exclude_none=True)
                                    data['type'] = _convert_format_string(data.get('type', fmt.type))
                                    converted_formats.append(data)
                                else:
                                    converted_formats.append(_convert_format_string(fmt.type))
                            else:
                                converted_formats.append(fmt)

                    # Add booleans from ScrapeFormats
                    if original_formats.markdown:
                        converted_formats.append("markdown")
                    if original_formats.html:
                        converted_formats.append("html")
                    if original_formats.raw_html:
                        converted_formats.append("rawHtml")
                    if original_formats.summary:
                        converted_formats.append("summary")
                    if original_formats.links:
                        converted_formats.append("links")
                    if original_formats.screenshot:
                        converted_formats.append("screenshot")
                    if original_formats.change_tracking:
                        converted_formats.append("changeTracking")
                    # Note: We intentionally do not auto-include 'json' when boolean is set,
                    # because JSON requires an object with schema/prompt. The caller must
                    # supply the full json format object explicitly.
                elif isinstance(original_formats, list):
                    for fmt in original_formats:
                        if isinstance(fmt, str):
                            if fmt == "json":
                                raise ValueError("json format must be an object with 'type', 'prompt', and 'schema' fields")
                            if fmt == "query":
                                raise ValueError("query format must be an object with 'type' and 'prompt' fields")
                            if fmt == "question":
                                raise ValueError("question format must be an object with 'type' and 'question' fields")
                            if fmt == "highlights":
                                raise ValueError("highlights format must be an object with 'type' and 'query' fields")
                            converted_formats.append(_convert_format_string(fmt))
                        elif isinstance(fmt, dict):
                            fmt_type = _convert_format_string(fmt.get('type')) if fmt.get('type') else None
                            if fmt_type == 'json':
                                validated_json = _validate_json_format({**fmt, 'type': 'json'})
                                converted_formats.append(validated_json)
                            elif fmt_type == 'question':
                                converted_formats.append(_validate_question_format(fmt))
                            elif fmt_type == 'highlights':
                                converted_formats.append(_validate_highlights_format(fmt))
                            elif fmt_type == 'query':
                                converted_formats.append(_validate_query_format(fmt))
                            elif fmt_type == 'screenshot':
                                normalized = {**fmt, 'type': 'screenshot'}
                                if 'full_page' in normalized:
                                    normalized['fullPage'] = normalized.pop('full_page')
                                vp = normalized.get('viewport')
                                if hasattr(vp, 'model_dump'):
                                    normalized['viewport'] = vp.model_dump(exclude_none=True)
                                converted_formats.append(normalized)
                            else:
                                if 'type' in fmt:
                                    fmt['type'] = fmt_type or fmt['type']
                                converted_formats.append(fmt)
                        elif hasattr(fmt, 'type'):
                            if fmt.type == 'json':
                                converted_formats.append(_validate_json_format(fmt.model_dump()))
                            elif fmt.type == 'question':
                                converted_formats.append(_validate_question_format(fmt.model_dump(exclude_none=True)))
                            elif fmt.type == 'highlights':
                                converted_formats.append(_validate_highlights_format(fmt.model_dump(exclude_none=True)))
                            elif fmt.type == 'screenshot':
                                normalized = {'type': 'screenshot'}
                                if getattr(fmt, 'full_page', None) is not None:
                                    normalized['fullPage'] = fmt.full_page
                                if getattr(fmt, 'quality', None) is not None:
                                    normalized['quality'] = fmt.quality
                                vp = getattr(fmt, 'viewport', None)
                                if vp is not None:
                                    normalized['viewport'] = vp.model_dump(exclude_none=True) if hasattr(vp, 'model_dump') else vp
                                converted_formats.append(normalized)
                            elif fmt.type == 'query':
                                converted_formats.append(_validate_query_format(fmt.model_dump(exclude_none=True)))
                            elif fmt.type in ('changeTracking', 'change_tracking'):
                                data = fmt.model_dump(exclude_none=True)
                                data['type'] = _convert_format_string(data.get('type', fmt.type))
                                converted_formats.append(data)
                            else:
                                converted_formats.append(_convert_format_string(fmt.type))
                        else:
                            converted_formats.append(fmt)
                else:
                    # Fallback: try to iterate over value if it's a list-like
                    try:
                        for fmt in value:
                            converted_formats.append(fmt)
                    except TypeError:
                        pass

                if converted_formats:
                    scrape_data["formats"] = converted_formats
            elif key == "actions":
                # Handle actions conversion
                converted_actions = []
                for action in value:
                    if isinstance(action, dict):
                        # Convert action dict
                        converted_action = {}
                        for action_key, action_value in action.items():
                            if action_key == "full_page":
                                converted_action["fullPage"] = action_value
                            else:
                                converted_action[action_key] = action_value
                        converted_actions.append(converted_action)
                    else:
                        # Handle action objects
                        action_data = action.model_dump(exclude_none=True)
                        converted_action = {}
                        for action_key, action_value in action_data.items():
                            if action_key == "full_page":
                                converted_action["fullPage"] = action_value
                            else:
                                converted_action[action_key] = action_value
                        converted_actions.append(converted_action)
                scrape_data["actions"] = converted_actions
            elif key == "parsers":
                converted_parsers = []
                for parser in value:
                    if isinstance(parser, str):
                        converted_parsers.append(parser)
                    elif isinstance(parser, dict):
                        parser_data = dict(parser)
                        if "max_pages" in parser_data:
                            parser_data["maxPages"] = parser_data.pop("max_pages")
                        # Deprecated alias from the pre-rename pageMarkdown option.
                        if "page_markdown" in parser_data:
                            parser_data.setdefault("pages", parser_data.pop("page_markdown"))
                        if "pageMarkdown" in parser_data:
                            parser_data.setdefault("pages", parser_data.pop("pageMarkdown"))
                        if "page_markers" in parser_data:
                            parser_data["pageMarkers"] = parser_data.pop("page_markers")
                        converted_parsers.append(parser_data)
                    else:
                        parser_data = parser.model_dump(exclude_none=True)
                        # Convert snake_case to camelCase for API
                        if "max_pages" in parser_data:
                            parser_data["maxPages"] = parser_data.pop("max_pages")
                        if "page_markers" in parser_data:
                            parser_data["pageMarkers"] = parser_data.pop("page_markers")
                        converted_parsers.append(parser_data)
                scrape_data["parsers"] = converted_parsers
            elif key == "location":
                if isinstance(value, dict):
                    scrape_data["location"] = value
                else:
                    scrape_data["location"] = value.model_dump(exclude_none=True)
            elif key == "profile":
                if isinstance(value, dict):
                    profile_data = {
                        "name": value["name"],
                        "saveChanges": value.get("save_changes", value.get("saveChanges", True)),
                    }
                else:
                    profile_data = {
                        "name": value.name,
                        "saveChanges": getattr(value, "save_changes", getattr(value, "saveChanges", True)),
                    }
                scrape_data["profile"] = profile_data
            else:
                # For fields that don't need conversion, use as-is
                scrape_data[key] = value

    return scrape_data

"""
WebSocket-based watcher for v2 jobs (crawl and batch), mirroring v1 behavior.

Usage:
    watcher = client.watcher(job_id, kind="crawl")
    watcher.add_listener(lambda status: print(status.status))
    watcher.start()
"""

import asyncio
import json
import threading
from typing import Callable, List, Optional, Literal, Union, Dict, Any

import websockets

from .types import CrawlJob, BatchScrapeJob, Document
from .utils.normalize import normalize_document_input


JobKind = Literal["crawl", "batch"]
JobType = Union[CrawlJob, BatchScrapeJob]


class Watcher:
    def __init__(
        self,
        client: object,
        job_id: str,
        kind: JobKind = "crawl",
        poll_interval: int = 2,
        timeout: Optional[int] = None,
    ) -> None:
        self._client = client
        self._job_id = job_id
        self._kind = kind
        self._timeout = timeout
        self._poll_interval = poll_interval
        self._listeners: List[Callable[[JobType], None]] = []
        self._thread: Optional[threading.Thread] = None
        self._stop = threading.Event()

        http_client = getattr(client, "http_client", None)
        self._api_url: Optional[str] = getattr(http_client, "api_url", None)
        self._api_key: Optional[str] = getattr(http_client, "api_key", None)

        # v1-parity state and event handlers
        self.status: str = "scraping"
        self.data: List[Dict[str, Any]] = []
        self._event_handlers: Dict[str, List[Callable[[Dict[str, Any]], None]]] = {
            "done": [],
            "error": [],
            "document": [],
        }
        self._sent_done: bool = False
        self._sent_error: bool = False

    def add_listener(self, callback: Callable[[JobType], None]) -> None:
        self._listeners.append(callback)

    def _emit(self, status: JobType) -> None:
        for cb in list(self._listeners):
            try:
                cb(status)
            except Exception:
                pass

    # v1-like events API
    def add_event_listener(self, event_type: str, handler: Callable[[Dict[str, Any]], None]) -> None:
        if event_type in self._event_handlers:
            self._event_handlers[event_type].append(handler)

    def dispatch_event(self, event_type: str, detail: Dict[str, Any]) -> None:
        if event_type in self._event_handlers:
            for handler in self._event_handlers[event_type]:
                try:
                    handler(detail)
                except Exception:
                    pass

    def _build_ws_url(self) -> str:
        if not self._api_url:
            raise ValueError("API URL is required for WebSocket watcher")
        ws_base = self._api_url.replace("https://", "wss://").replace("http://", "ws://", 1)
        if self._kind == "crawl":
            return f"{ws_base}/v2/crawl/{self._job_id}"
        return f"{ws_base}/v2/batch/scrape/{self._job_id}"

    async def _run_ws(self) -> None:
        uri = self._build_ws_url()
        headers_list = []
        if self._api_key:
            headers_list.append(("Authorization", f"Bearer {self._api_key}"))

        try:
            async with websockets.connect(uri, max_size=None, additional_headers=headers_list) as websocket:
                deadline = asyncio.get_event_loop().time() + self._timeout if self._timeout else None
                while not self._stop.is_set():
                    # Use short recv timeouts to allow HTTP polling fallback
                    if deadline is not None:
                        remaining = max(0.0, deadline - asyncio.get_event_loop().time())
                        timeout = min(self._poll_interval or remaining, remaining)
                    else:
                        timeout = self._poll_interval or 5
                    try:
                        msg = await asyncio.wait_for(websocket.recv(), timeout=timeout)
                    except asyncio.TimeoutError:
                        # Quiet period: poll HTTP once to progress statuses
                        if await self._poll_status_once():
                            break
                        else:
                            continue
                    except asyncio.CancelledError:
                        break
                    except Exception:
                        # Connection error: switch to HTTP polling until terminal or timeout
                        while not self._stop.is_set():
                            if await self._poll_status_once():
                                return
                            if deadline is not None and asyncio.get_event_loop().time() >= deadline:
                                return
                            await asyncio.sleep(self._poll_interval or 2)
                        return

                    try:
                        body = json.loads(msg)
                    except Exception:
                        continue

                    # v1-style typed event handling
                    msg_type = body.get("type")
                    if msg_type == "error":
                        self.status = "failed"
                        self.dispatch_event("error", {
                            "status": self.status,
                            "data": self.data,
                            "error": body.get("error"),
                            "id": self._job_id,
                        })
                        self._sent_error = True
                        # Emit a final failed snapshot for listeners
                        if self._kind == "crawl":
                            job = CrawlJob(status="failed", completed=0, total=0, credits_used=0, expires_at=None, next=None, data=[])
                        else:
                            job = BatchScrapeJob(status="failed", completed=0, total=0, credits_used=0, expires_at=None, next=None, data=[])
                        self._emit(job)
                        break
                    elif msg_type == "catchup":
                        d = body.get("data", {})
                        self.status = d.get("status", self.status)
                        docs_in = d.get("data", [])
                        self.data.extend(docs_in)
                        for doc in docs_in:
                            self.dispatch_event("document", {"data": doc, "id": self._job_id})
                    elif msg_type == "document":
                        doc = body.get("data")
                        if isinstance(doc, dict):
                            self.data.append(doc)
                            self.dispatch_event("document", {"data": doc, "id": self._job_id})
                    elif msg_type == "done":
                        self.status = "completed"
                        # Gather any documents in the done payload
                        raw_payload = body.get("data", {}) or {}
                        docs_in = raw_payload.get("data", []) or []
                        if isinstance(docs_in, list) and docs_in:
                            for doc in docs_in:
                                if isinstance(doc, dict):
                                    self.data.append(doc)
                        # Dispatch done event first
                        self.dispatch_event("done", {"status": self.status, "data": self.data, "id": self._job_id})
                        self._sent_done = True
                        # Emit a final completed snapshot for listeners and break immediately
                        docs: List[Document] = []
                        for doc in self.data:
                            if isinstance(doc, dict):
                                d = normalize_document_input(doc)
                                docs.append(Document(**d))
                        if self._kind == "crawl":
                            job = CrawlJob(
                                status="completed",
                                completed=raw_payload.get("completed", 0),
                                total=raw_payload.get("total", 0),
                                credits_used=raw_payload.get("creditsUsed", 0),
                                expires_at=raw_payload.get("expiresAt"),
                                next=raw_payload.get("next"),
                                data=docs,
                            )
                        else:
                            job = BatchScrapeJob(
                                status="completed",
                                completed=raw_payload.get("completed", 0),
                                total=raw_payload.get("total", 0),
                                credits_used=raw_payload.get("creditsUsed", 0),
                                expires_at=raw_payload.get("expiresAt"),
                                next=raw_payload.get("next"),
                                data=docs,
                            )
                        self._emit(job)
                        break

                    payload = body.get("data", body)
                    # Only treat messages with an explicit status as job snapshots
                    has_status_field = (isinstance(payload, dict) and "status" in payload) or ("status" in body)
                    if not has_status_field:
                        continue
                    status_str = payload.get("status", body.get("status", self.status))

                    if self._kind == "crawl":
                        docs = []
                        for doc in payload.get("data", []):
                            if isinstance(doc, dict):
                                d = normalize_document_input(doc)
                                docs.append(Document(**d))
                        job = CrawlJob(
                            status=status_str,
                            completed=payload.get("completed", 0),
                            total=payload.get("total", 0),
                            credits_used=payload.get("creditsUsed", 0),
                            expires_at=payload.get("expiresAt"),
                            next=payload.get("next"),
                            data=docs,
                        )
                        self._emit(job)
                        if status_str in ("completed", "failed", "cancelled"):
                            # Ensure done/error dispatched even if server didn't send explicit event type
                            if status_str == "completed" and not self._sent_done:
                                self.dispatch_event("done", {"status": status_str, "data": self.data, "id": self._job_id})
                                self._sent_done = True
                            if status_str == "failed" and not self._sent_error:
                                self.dispatch_event("error", {"status": status_str, "data": self.data, "id": self._job_id})
                                self._sent_error = True
                            break
                    else:
                        docs = []
                        for doc in payload.get("data", []):
                            if isinstance(doc, dict):
                                d = normalize_document_input(doc)
                                docs.append(Document(**d))
                        job = BatchScrapeJob(
                            status=status_str,
                            completed=payload.get("completed", 0),
                            total=payload.get("total", 0),
                            credits_used=payload.get("creditsUsed"),
                            expires_at=payload.get("expiresAt"),
                            next=payload.get("next"),
                            data=docs,
                        )
                        self._emit(job)
                        if status_str in ("completed", "failed", "cancelled"):
                            if status_str == "completed" and not self._sent_done:
                                self.dispatch_event("done", {"status": status_str, "data": self.data, "id": self._job_id})
                                self._sent_done = True
                            if status_str == "failed" and not self._sent_error:
                                self.dispatch_event("error", {"status": status_str, "data": self.data, "id": self._job_id})
                                self._sent_error = True
                            break
        except Exception:
            pass
        finally:
            # Ensure terminal event parity with v1 even on abrupt disconnects
            if self.status == "completed" and not self._sent_done:
                self.dispatch_event("done", {"status": self.status, "data": self.data, "id": self._job_id})
                self._sent_done = True

    async def _poll_status_once(self) -> bool:
        """Poll job status over HTTP once. Returns True if terminal."""
        try:
            if self._kind == "crawl":
                job: CrawlJob = await asyncio.to_thread(self._client.get_crawl_status, self._job_id)
            else:
                job: BatchScrapeJob = await asyncio.to_thread(self._client.get_batch_scrape_status, self._job_id)
        except Exception:
            return False

        self.status = job.status
        self._emit(job)
        if job.status in ("completed", "failed", "cancelled"):
            if job.status == "completed" and not self._sent_done:
                self.dispatch_event("done", {"status": job.status, "data": [d.model_dump() for d in job.data], "id": self._job_id})
                self._sent_done = True
            if job.status == "failed" and not self._sent_error:
                self.dispatch_event("error", {"status": job.status, "data": [d.model_dump() for d in job.data], "id": self._job_id})
                self._sent_error = True
            return True
        return False

    def _loop(self) -> None:
        asyncio.run(self._run_ws())

    def start(self) -> None:
        if self._thread and self._thread.is_alive():
            return
        self._stop.clear()
        self._thread = threading.Thread(target=self._loop, daemon=True)
        self._thread.start()

    def stop(self) -> None:
        self._stop.set()
        if self._thread:
            self._thread.join(timeout=1)

"""
Async WebSocket watcher with async iterator interface for v2 jobs.

Usage:
    async for snapshot in AsyncWatcher(client, job_id, kind="crawl"):
        print(snapshot.status)
"""

import asyncio
import inspect
import json
import time
from typing import AsyncIterator, Dict, List, Literal, Optional

import websockets
from websockets.exceptions import ConnectionClosed, ConnectionClosedOK, ConnectionClosedError

from .types import BatchScrapeJob, CrawlJob, Document
from .utils.normalize import normalize_document_input

JobKind = Literal["crawl", "batch"]


class AsyncWatcher:
    def __init__(
        self,
        client: object,
        job_id: str,
        *,
        kind: JobKind = "crawl",
        poll_interval: int = 2,
        timeout: Optional[int] = None,
    ) -> None:
        self._client = client
        self._job_id = job_id
        self._kind = kind
        self._timeout = timeout
        self._poll_interval: float = max(0.0, float(poll_interval))  # Guard against negative values

        http_client = getattr(client, "http_client", None)
        if http_client is not None:
            self._api_url = getattr(http_client, "api_url", None)
            self._api_key = getattr(http_client, "api_key", None)
        else:
            # Allow passing the top-level Firecrawl client directly
            self._api_url = getattr(client, "api_url", None)
            self._api_key = getattr(client, "api_key", None)

        self._status: str = "scraping"
        self._data: List[Dict] = []

    def __aiter__(self) -> AsyncIterator[object]:
        return self._iterate()

    def _build_ws_url(self) -> str:
        if not self._api_url:
            raise ValueError("API URL is required for WebSocket watcher")
        ws_base = self._api_url.replace("https://", "wss://").replace("http://", "ws://", 1)
        if self._kind == "crawl":
            return f"{ws_base}/v2/crawl/{self._job_id}"
        return f"{ws_base}/v2/batch/scrape/{self._job_id}"

    async def _iterate(self) -> AsyncIterator[object]:
        uri = self._build_ws_url()
        headers_list = []
        if self._api_key:
            headers_list.append(("Authorization", f"Bearer {self._api_key}"))

        # Attempt to establish WS; on failure, fall back to HTTP polling immediately
        try:
            async with websockets.connect(uri, max_size=None, additional_headers=headers_list) as websocket:
                deadline = asyncio.get_event_loop().time() + self._timeout if self._timeout else None
                # Pre-yield a snapshot if available to ensure progress is visible
                try:
                    pre = await self._fetch_job_status()
                    yield pre
                    if pre.status in ("completed", "failed", "cancelled"):
                        return
                except Exception:
                    pass

                while True:
                    try:
                        if deadline is not None:
                            remaining = max(0.0, deadline - asyncio.get_event_loop().time())
                            timeout = min(self._poll_interval, remaining) if remaining > 0 else 0.0
                        else:
                            timeout = self._poll_interval
                        msg = await asyncio.wait_for(websocket.recv(), timeout=timeout)
                    except asyncio.TimeoutError:
                        # Quiet period: poll HTTP once
                        job = await self._safe_fetch()
                        if job is not None:
                            yield job
                            if job.status in ("completed", "failed", "cancelled"):
                                return
                        if deadline is not None and asyncio.get_event_loop().time() >= deadline:
                            return
                        continue
                    except (ConnectionClosedOK, ConnectionClosed, ConnectionClosedError):
                        # Graceful/abrupt close: poll HTTP until terminal (bounded by timeout)
                        deadline = time.time() + (self._timeout or 30)
                        while True:
                            try:
                                job = await self._fetch_job_status()
                                yield job
                                if job.status in ("completed", "failed", "cancelled"):
                                    return
                            except Exception:
                                return
                            if time.time() >= deadline:
                                return
                            await asyncio.sleep(1)
                    try:
                        body = json.loads(msg)
                    except Exception:
                        continue

                    msg_type = body.get("type")
                    if msg_type == "error":
                        self._status = "failed"
                        # Yield a terminal snapshot
                        if self._kind == "crawl":
                            yield CrawlJob(status="failed", completed=0, total=0, credits_used=0, expires_at=None, next=None, data=[])
                        else:
                            yield BatchScrapeJob(status="failed", completed=0, total=0, credits_used=0, expires_at=None, next=None, data=[])
                        return
                    elif msg_type == "catchup":
                        d = body.get("data", {})
                        self._status = d.get("status", self._status)
                        docs_in = d.get("data", []) or []
                        self._data.extend(docs_in)
                        # Fall through to emit a snapshot below
                    elif msg_type == "document":
                        doc = body.get("data")
                        if isinstance(doc, dict):
                            self._data.append(doc)
                        # Fall through to emit a snapshot below
                    elif msg_type == "done":
                        self._status = "completed"
                        raw_payload = body.get("data", {}) or {}
                        docs_in = raw_payload.get("data", []) or []
                        if isinstance(docs_in, list) and docs_in:
                            for doc in docs_in:
                                if isinstance(doc, dict):
                                    self._data.append(doc)
                        # Emit final snapshot then end
                        yield self._make_snapshot(status="completed", payload=raw_payload, docs_override=self._data)
                        return

                    # Generic snapshot emit for status messages and periodic progress
                    payload = body.get("data", body)
                    status_str = payload.get("status", body.get("status", self._status))
                    snapshot = self._make_snapshot(status=status_str, payload=payload)
                    yield snapshot
                    if status_str in ("completed", "failed", "cancelled"):
                        return
        except Exception:
            # WS connect failure: fallback to HTTP polling loop until terminal/timeout
            deadline = time.time() + (self._timeout or 30)
            while True:
                try:
                    job = await self._fetch_job_status()
                    yield job
                    if job.status in ("completed", "failed", "cancelled"):
                        return
                except Exception:
                    return
                if time.time() >= deadline:
                    return
                await asyncio.sleep(1)

    async def _fetch_job_status(self):
        if self._kind == "crawl":
            return await self._call_status_method("get_crawl_status")
        return await self._call_status_method("get_batch_scrape_status")

    async def _call_status_method(self, method_name: str):
        # Try on client directly
        meth = getattr(self._client, method_name, None)
        if meth is not None:
            try:
                result = meth(self._job_id)
            except TypeError:
                result = None
            if result is not None:
                if inspect.isawaitable(result):
                    return await result
                return result
            # Fallback: if we couldn't call directly, try to_thread
            return await asyncio.to_thread(meth, self._job_id)

        # Try on client.v2
        v2 = getattr(self._client, "v2", None)
        if v2 is not None:
            meth = getattr(v2, method_name, None)
            if meth is not None:
                try:
                    result = meth(self._job_id)
                except TypeError:
                    result = None
                if result is not None:
                    if inspect.isawaitable(result):
                        return await result
                    return result
                return await asyncio.to_thread(meth, self._job_id)

        raise RuntimeError(f"Client does not expose {method_name}")

    async def _safe_fetch(self):
        try:
            return await self._fetch_job_status()
        except Exception:
            return None

    def _make_snapshot(self, *, status: str, payload: Dict, docs_override: Optional[List[Dict]] = None):
        docs = []
        source_docs = docs_override if docs_override is not None else payload.get("data", []) or []
        for doc in source_docs:
            if isinstance(doc, dict):
                d = normalize_document_input(doc)
                docs.append(Document(**d))

        if self._kind == "crawl":
            return CrawlJob(
                status=status,
                completed=payload.get("completed", 0),
                total=payload.get("total", 0),
                credits_used=payload.get("creditsUsed", 0),
                expires_at=payload.get("expiresAt"),
                next=payload.get("next"),
                data=docs,
            )
        return BatchScrapeJob(
            status=status,
            completed=payload.get("completed", 0),
            total=payload.get("total", 0),
            credits_used=payload.get("creditsUsed"),
            expires_at=payload.get("expiresAt"),
            next=payload.get("next"),
            data=docs,
        )

import unittest
from unittest.mock import patch, MagicMock
import json
